func TestCancelledPromptWritesNothingAndFails(t *testing.T) {
	t.Parallel()

	root := scratchProject(t)
	t.Setenv(interactive.EnvTestTTY, "1")
	t.Setenv(uiform.EnvAccessible, "1")

